// 24-S4 acceptance: live sync by polling (`poller.ts`) and the queue's side
// of catching up (`OperationQueue.catchUp`, `resync`). Pure, with fake
// timers. Do not edit this file to match an implementation.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createGrid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import type { CatchUp, CommittedOperation } from './catchup';
import type { CommitOutcome } from './commit';
import type { Operation } from './operation';
import {
  CatchUpPoller, parseCatchUp, POLL_INTERVAL_MS, POLL_RETRY_DELAYS_MS, type PollerDeps, type PollOutcome,
} from './poller';
import { OperationQueue, type QueueDeps } from './queue';

beforeEach(() => { vi.useFakeTimers(); });
afterEach(() => { vi.useRealTimers(); });

const flush = () => vi.advanceTimersByTimeAsync(0);

function pollerHarness(overrides: Partial<PollerDeps> = {}) {
  const asked: Array<number | null> = [];
  const replies: Array<{ resolve: (result: CatchUp) => void; reject: (error: unknown) => void }> = [];
  const state = { visible: true, version: 3, outcome: 'ok' as PollOutcome };
  const applied: CatchUp[] = [];
  const poller = new CatchUpPoller({
    fetch: (since) => {
      asked.push(since);
      return new Promise((resolve, reject) => replies.push({ resolve, reject }));
    },
    since: () => state.version,
    apply: (result) => { applied.push(result); return state.outcome; },
    isVisible: () => state.visible,
    ...overrides,
  });
  const reply = async (result: CatchUp = { status: 'ops', ops: [] }) => { replies.shift()!.resolve(result); await flush(); };
  const failReply = async () => { replies.shift()!.reject(new Error('offline')); await flush(); };
  return { poller, asked, replies, state, applied, reply, failReply };
}

describe('24-S4-4 polling while visible', () => {
  it('asks at once, then about once a second from the confirmed version, one request at a time', async () => {
    const { poller, asked, reply, state } = pollerHarness();
    poller.start();
    expect(asked).toEqual([3]);
    await vi.advanceTimersByTimeAsync(5000);
    expect(asked).toEqual([3]);
    state.version = 5;
    await reply();
    expect(asked).toEqual([3]);
    await vi.advanceTimersByTimeAsync(POLL_INTERVAL_MS - 1);
    expect(asked).toEqual([3]);
    await vi.advanceTimersByTimeAsync(1);
    expect(asked).toEqual([3, 5]);
    expect(POLL_INTERVAL_MS).toBe(1000);
  });

  it('stops while hidden and asks at once on becoming visible again', async () => {
    const { poller, asked, reply, state } = pollerHarness();
    poller.start();
    await reply();
    state.visible = false;
    poller.pause();
    await vi.advanceTimersByTimeAsync(10_000);
    expect(asked).toHaveLength(1);
    state.visible = true;
    poller.pollNow();
    expect(asked).toHaveLength(2);
  });

  it('a request in flight when hidden finishes but schedules no more', async () => {
    const { poller, asked, reply, state } = pollerHarness();
    poller.start();
    state.visible = false;
    poller.pause();
    await reply();
    await vi.advanceTimersByTimeAsync(10_000);
    expect(asked).toHaveLength(1);
  });

  it('asking now while one is in flight asks again as soon as it is answered', async () => {
    const { poller, asked, reply } = pollerHarness();
    poller.start();
    poller.pollNow();
    poller.pollNow();
    expect(asked).toHaveLength(1);
    await reply();
    expect(asked).toHaveLength(2);
  });

  it('a failed request is tried again after a growing delay; back online, at once', async () => {
    const { poller, asked, failReply, reply } = pollerHarness();
    poller.start();
    await failReply();
    await vi.advanceTimersByTimeAsync(POLL_RETRY_DELAYS_MS[0]);
    expect(asked).toHaveLength(2);
    await failReply();
    await vi.advanceTimersByTimeAsync(POLL_RETRY_DELAYS_MS[1] - 1);
    expect(asked).toHaveLength(2);
    await vi.advanceTimersByTimeAsync(1);
    expect(asked).toHaveLength(3);
    await failReply();
    poller.pollNow();
    expect(asked).toHaveLength(4);
    await reply();
    await vi.advanceTimersByTimeAsync(POLL_INTERVAL_MS);
    expect(asked).toHaveLength(5);
  });

  it('a divergence asks for the snapshot next; a failed snapshot request asks for it again', async () => {
    const { poller, asked, reply, failReply, state } = pollerHarness();
    poller.start();
    state.outcome = 'resync';
    await reply();
    expect(asked).toEqual([3, null]);
    state.outcome = 'ok';
    await failReply();
    await vi.advanceTimersByTimeAsync(POLL_RETRY_DELAYS_MS[0]);
    expect(asked).toEqual([3, null, null]);
    await reply();
    await vi.advanceTimersByTimeAsync(POLL_INTERVAL_MS);
    expect(asked).toEqual([3, null, null, 3]);
  });

  it('stops for good when told to, or when the caller stops it', async () => {
    const { poller, asked, reply, state } = pollerHarness();
    poller.start();
    state.outcome = 'stop';
    await reply();
    await vi.advanceTimersByTimeAsync(10_000);
    poller.pollNow();
    expect(asked).toHaveLength(1);

    const other = pollerHarness();
    other.poller.start();
    await other.reply();
    other.poller.stop();
    await vi.advanceTimersByTimeAsync(10_000);
    expect(other.asked).toHaveLength(1);
  });
});

describe('24-S4-5 the catch-up answer as the editor reads it', () => {
  const op = { opId: 'o1', puzzleId: 'p', clientId: 'c', epoch: 0, baseVersion: 2, kind: 'title', title: 'X', version: 3 };
  it('keeps well-formed operations, the snapshot and the refusals; anything else is null', () => {
    expect(parseCatchUp({ status: 'ops', ops: [op] }, 'p')).toEqual({ status: 'ops', ops: [op] });
    expect(parseCatchUp({ status: 'not-found' }, 'p')).toEqual({ status: 'not-found' });
    const content = { grid: serializeGrid(createGrid({ cols: 3, rows: 3 })), hints: {}, title: 'T', phase: 'grid' };
    expect(parseCatchUp({ status: 'snapshot', version: 4, resetEpoch: 1, content }, 'p'))
      .toEqual({ status: 'snapshot', version: 4, resetEpoch: 1, content });
    for (const bad of [
      null, 'x', { status: 'ops' }, { status: 'ops', ops: [{ ...op, version: -1 }] }, { status: 'ops', ops: [{ ...op, puzzleId: 'q' }] },
      { status: 'ops', ops: [{ ...op, kind: 'nope' }] }, { status: 'snapshot', version: 4, resetEpoch: 1, content: { ...content, phase: 'x' } },
    ]) expect(parseCatchUp(bad, 'p')).toBeNull();
  });
});

const initial = {
  confirmed: {
    content: { grid: serializeGrid(createGrid({ cols: 3, rows: 3 })), hints: {}, title: 'T', phase: 'grid' as const },
    version: 0, resetEpoch: 0,
  },
  pending: [],
};

function queueHarness(overrides: Partial<QueueDeps> = {}) {
  const sent: Operation[] = [];
  const answers: Array<{ resolve: (outcome: CommitOutcome) => void; reject: (error: unknown) => void }> = [];
  const onBehind = vi.fn();
  const journal = vi.fn();
  let n = 0;
  const queue = new OperationQueue(initial, { puzzleId: 'p', clientId: 'tab', newOpId: () => `op-${++n}` }, {
    send: (op) => { sent.push(op); return new Promise((resolve, reject) => answers.push({ resolve, reject })); },
    onBehind, journal, retryDelaysMs: [1000], ...overrides,
  });
  const answer = async (outcome: CommitOutcome) => { answers.shift()!.resolve(outcome); await flush(); };
  const fail = async () => { answers.shift()!.reject(new Error('offline')); await flush(); };
  return { queue, sent, answer, fail, onBehind, journal };
}
const committed = (op: Operation, version: number) => ({ ...op, version }) as CommittedOperation;
const elsewhere = (version: number, title = `E${version}`): CommittedOperation => ({
  opId: `e-${version}`, puzzleId: 'p', clientId: 'other', epoch: 0, baseVersion: version - 1, kind: 'title', title, version,
});

describe('24-S4-6 the queue catching up', () => {
  it('an acceptance ahead of the confirmed version asks to catch up; catching up applies it once', async () => {
    const { queue, answer, onBehind } = queueHarness();
    const op = queue.add({ kind: 'title', title: 'Mine' });
    await answer({ status: 'accepted', opId: op.opId, version: 3 });
    expect(onBehind).toHaveBeenCalledTimes(1);
    expect(queue.outbox.confirmed.version).toBe(0);
    expect(queue.queueState).toBe('idle');
    expect(queue.catchUp([elsewhere(1), elsewhere(2), committed(op, 3)])).toBe(false);
    expect(queue.outbox).toEqual({ ...initial, confirmed: { ...initial.confirmed, content: { ...initial.confirmed.content, title: 'Mine' }, version: 3 } });
  });

  it('an operation shown committed by catching up is answered: its waiters resolve, it is not sent again, a retry is called off', async () => {
    const { queue, sent, fail, journal } = queueHarness();
    const first = queue.add({ kind: 'title', title: 'A' });
    const second = queue.add({ kind: 'title', title: 'B' });
    const waiting = queue.settled(first.opId);
    await fail();
    expect(queue.queueState).toBe('retrying');
    queue.catchUp([committed(first, 1)]);
    await flush();
    expect(await waiting).toEqual({ status: 'accepted', version: 1 });
    expect(queue.outbox.pending.map((op) => op.opId)).toEqual([second.opId]);
    expect(journal).toHaveBeenLastCalledWith([second]);
    expect(sent.map((op) => op.opId)).toEqual([first.opId, second.opId]);
    expect(queue.queueState).toBe('saving');
  });

  it('the answer for an operation in flight that catching up already applied changes nothing; a lost one is not retried', async () => {
    const { queue, sent, answer, fail } = queueHarness();
    const first = queue.add({ kind: 'title', title: 'A' });
    queue.catchUp([committed(first, 1)]);
    const after = queue.outbox;
    await answer({ status: 'accepted', opId: first.opId, version: 1 });
    expect(queue.outbox).toBe(after);

    const second = queue.add({ kind: 'title', title: 'B' });
    queue.catchUp([committed(second, 2)]);
    await fail();
    expect(queue.queueState).toBe('idle');
    await vi.advanceTimersByTimeAsync(5000);
    expect(sent.map((op) => op.opId)).toEqual([first.opId, second.opId]);
  });

  it('the snapshot becomes the confirmed state, pending work kept', () => {
    const { queue } = queueHarness();
    queue.add({ kind: 'title', title: 'Pending' });
    const content = { ...initial.confirmed.content, title: 'Stored' };
    queue.resync({ content, version: 9, resetEpoch: 2 });
    expect(queue.outbox.confirmed).toEqual({ content, version: 9, resetEpoch: 2 });
    expect(queue.outbox.pending).toHaveLength(1);
  });
});
